{"path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>{{BUSINESS_NAME}} — Practical wellbeing events & series</title>
  <meta name="description" content="Actionable routines, clear frameworks, and supportive series to shape daily wellbeing habits in {{CITY}}, {{STATE}}.">
  <link rel="stylesheet" href="assets/css/styles.css">
</head>
<body class="layout-bold">
  <header class="site-header">
    <div class="wrap">
      <a class="brand" href="index.html">{{BUSINESS_NAME}}</a>
      <nav class="nav">
        <a href="index.html">Start</a>
        <a href="programs.html">Blueprints</a>
        <a href="services.html">Rituals</a>
        <a href="pricing.html">Invest</a>
        <a href="testimonials.html">Voices</a>
        <a href="book.html">Reserve</a>
        <a href="contact.html">Connect</a>
      </nav>
      <div class="header-actions">
        <a class="btn btn-ghost" href="tel:{{PHONE}}">Call</a>
        <a class="btn btn-primary" id="primaryCtaTop" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
      </div>
    </div>
  </header>

  <main>
    <!-- HERO with Mood-to-Method selector -->
    <section class="hero" id="hero">
      <div class="wrap hero-grid">
        <div class="hero-left">
          <h1>Intentional shifts, simple daily steps.</h1>
          <p class="lead">I lead small guided series and monthly gatherings that translate big wellbeing ideas into reliable habits. Choose how you feel and get a clear next step.</p>

          <div class="mood-module" id="moodHero">
            <label class="mood-label">How are you right now?</label>
            <div class="mood-options" role="tablist">
              <button class="mood-btn" data-method="micro" data-cta="Try a 2-week micro-series">Stuck</button>
              <button class="mood-btn" data-method="rhythm" data-cta="Join the Monthly Rhythm">Overwhelmed</button>
              <button class="mood-btn" data-method="reset" data-cta="Book a Reset Session">Aiming for change</button>
              <button class="mood-btn" data-method="explore" data-cta="Explore Short Labs">Curious</button>
            </div>

            <div class="mood-result">
              <strong class="method-title">Recommended approach</strong>
              <p class="method-copy" id="methodCopy">Select how you feel to see a clear next step and a tailored invitation.</p>
              <a id="moodCta" class="btn btn-primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
            </div>
          </div>
        </div>

        <div class="hero-right pattern-wrap">
          <svg class="pattern" viewBox="0 0 200 200" preserveAspectRatio="none">
            <defs>
              <pattern id="p1" x="0" y="0" width="20" height="20" patternUnits="userSpaceOnUse">
                <rect x="0" y="0" width="10" height="10" fill="#ffd1b6"></rect>
                <rect x="10" y="10" width="10" height="10" fill="#f7e4c7"></rect>
              </pattern>
            </defs>
            <rect width="100%" height="100%" fill="url(#p1)"></rect>
          </svg>
          <div class="hero-card">
            <h3>Upcoming series: Momentum Monthly</h3>
            <p>Four 60-minute sessions that build a repeatable habit, with homework, templates and community accountability.</p>
            <div class="meta">Next cohort starts soon • Online</div>
            <a class="btn btn-outline" href="programs.html">See cohorts</a>
          </div>
        </div>
      </div>
    </section>

    <!-- STORY (values + outcomes) -->
    <section class="story wrap" id="story">
      <h2>Why this method works (not a quick fix)</h2>
      <div class="story-grid">
        <div>
          <h4>Small, visible habits</h4>
          <p>We design micro-practices you can do in real life: five-minute resets, evening rituals, and two-step check-ins that build confidence over weeks.</p>
        </div>
        <div>
          <h4>Outcome-focused frameworks</h4>
          <p>Each series maps to a framework — set, sustain, scale — so you always know the next actionable move without guesswork.</p>
        </div>
        <div>
          <h4>Peer-backed learning</h4>
          <p>Group speedtracks and shared experiments mean habits stick because they’re social and repeatable, not solitary.</p>
        </div>
      </div>
    </section>

    <!-- FRAMEWORK + Mood-to-Method repeated (second instance) -->
    <section class="framework wrap" id="framework">
      <h2>Our core blueprint: Set • Sustain • Scale</h2>
      <p class="sub">A concise approach to habit design that fits into busy lives.</p>
      <div class="framework-grid">
        <div>
          <h4>Set</h4>
          <p>Clarify a single, measurable behavior and an anchor moment to attach it to your day.</p>
        </div>
        <div>
          <h4>Sustain</h4>
          <p>Introduce accountability loops and tiny adjustments so the behavior travels beyond good intentions.</p>
        </div>
        <div>
          <h4>Scale</h4>
          <p>Layer on simple expansions that grow the practice without doubling time investment.</p>
        </div>
      </div>

      <div class="mood-module" id="moodFramework">
        <label class="mood-label">Pick a state for a tailored framework</label>
        <div class="mood-options">
          <button class="mood-btn" data-method="micro" data-cta="Start a focused mini-plan">Stuck</button>
          <button class="mood-btn" data-method="rhythm" data-cta="Join the group rhythm">Overwhelmed</button>
          <button class="mood-btn" data-method="reset" data-cta="Reserve my reset">Aiming for change</button>
        </div>
        <div class="mood-result">
          <strong class="method-title">Tailored blueprint</strong>
          <p class="method-copy" id="methodCopy2">Choose a state to see the specific rhythm and the suggested next step.</p>
          <a id="moodCta2" class="btn btn-primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
        </div>
      </div>
    </section>

    <!-- OFFERS -->
    <section class="offers wrap" id="offers">
      <h2>Offerings</h2>
      <div class="offers-grid">
        <article class="offer">
          <h3>Micro-Series</h3>
          <p>2-week guided experiments with daily prompts and a closing practice to keep.</p>
          <ul>
            <li>14 lessons</li>
            <li>Weekly group check-ins</li>
            <li>Practice templates</li>
          </ul>
        </article>

        <article class="offer">
          <h3>Momentum Monthly</h3>
          <p>Monthly cohorted sessions to set a single habit and anchor it into your routine.</p>
          <ul>
            <li>4 live sessions</li>
            <li>Accountability buddies</li>
            <li>Resource pack</li>
          </ul>
        </article>

        <article class="offer">
          <h3>Reset Session</h3>
          <p>One-off 60-minute strategy session for a quick, prioritized plan you can implement immediately.</p>
        </article>
      </div>
    </section>

    <!-- PRICING with comparator -->
    <section class="pricing wrap" id="pricing">
      <h2>Investment</h2>
      <p class="sub">Transparent pricing framed as either monthly commitment or packaged bundles.</p>

      <div class="pricing-toggle">
        <span class="label">Show prices:</span>
        <button id="priceToggle" class="toggle">Monthly</button>
      </div>

      <div class="pricing-grid" id="pricingGrid">
        <div class="plan" data-monthly="49" data-package="199">
          <h3>Micro-Series</h3>
          <div class="price"><span class="price-amount">$49</span><span class="price-label">/month</span></div>
          <p>Short experiments to shift one habit.</p>
          <a class="btn btn-outline" href="programs.html">Join</a>
        </div>

        <div class="plan" data-monthly="89" data-package="349">
          <h3>Momentum Monthly</h3>
          <div class="price"><span class="price-amount">$89</span><span class="price-label">/month</span></div>
          <p>Ongoing cohort to make a practice persistent.</p>
          <a class="btn btn-outline" href="programs.html">See dates</a>
        </div>

        <div class="plan" data-monthly="129" data-package="499">
          <h3>Reset Session</h3>
          <div class="price"><span class="price-amount">$129</span><span class="price-label">/one-off</span></div>
          <p>Focused 1:1 planning and immediate steps.</p>
          <a class="btn btn-outline" href="book.html">Reserve</a>
        </div>
      </div>
    </section>

    <!-- TESTIMONIALS -->
    <section class="testimonials wrap" id="testimonials">
      <h2>Voices from recent cohorts</h2>
      <div class="testimonials-grid">
        <blockquote>
          "The two-week micro-series gave me a daily practice I actually keep — small wins every morning."
          <cite>— A participant in Momentum Monthly</cite>
        </blockquote>
        <blockquote>
          "I found a simple evening ritual that took 5 minutes and changed how my day finishes. Worth every penny."
          <cite>— Member, Micro-Series</cite>
        </blockquote>
      </div>
    </section>

    <!-- CTA -->
    <section class="cta wrap" id="cta">
      <div class="cta-inner">
        <h2>Ready for a clear next step?</h2>
        <p>Pick a mood above or book a short strategy call to identify the first habit that moves the needle.</p>
        <div class="cta-actions">
          <a class="btn btn-primary" href="{{PRIMARY_CTA_URL}}" id="primaryCtaBottom">{{PRIMARY_CTA_LABEL}}</a>
          <a class="btn btn-ghost" href="contact.html">Connect via email</a>
        </div>
      </div>
    </section>
  </main>

  <footer class="site-footer">
    <div class="wrap footer-grid">
      <div>
        <strong>{{BUSINESS_NAME}}</strong>
        <div class="muted">Events & guided series in {{CITY}}, {{STATE}}</div>
      </div>
      <div>
        <div>Phone: <a href="tel:{{PHONE}}">{{PHONE}}</a></div>
        <div>Email: <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></div>
      </div>
      <div>
        <nav>
          <a href="about.html">About</a>
          <a href="programs.html">Programs</a>
          <a href="book.html">Book</a>
        </nav>
      </div>
    </div>
  </footer>

  <script src="assets/js/main.js" defer></script>
</body>
</html>"} 
