{"path":"assets/css/styles.css","content":"/* Bold & playful theme */
:root{--bg:#fff6f1;--accent:#ff7a4d;--accent-2:#ffd1b6;--ink:#1d1d1f;--muted:#6b6b6b;--card:#ffffff}
*{box-sizing:border-box}
body{font-family:Arial, Helvetica, sans-serif;color:var(--ink);background:var(--bg);line-height:1.45;margin:0}
.wrap{max-width:1100px;margin:0 auto;padding:32px}
.site-header{background:linear-gradient(90deg,rgba(255,122,77,0.06),transparent);border-bottom:1px solid rgba(29,29,31,0.04)}
.site-header .wrap{display:flex;align-items:center;gap:20px}
.brand{font-weight:800;color:var(--ink);text-decoration:none;font-size:20px}
.nav{display:flex;gap:12px;margin-left:8px}
.nav a{color:var(--ink);text-decoration:none;padding:8px 6px;border-radius:6px}
.nav a:hover{background:rgba(29,29,31,0.03)}
.header-actions{margin-left:auto;display:flex;gap:8px}
.btn{display:inline-block;padding:10px 14px;border-radius:8px;text-decoration:none;cursor:pointer}
.btn-primary{background:var(--accent);color:white;font-weight:700}
.btn-outline{border:2px solid var(--accent);color:var(--accent);background:transparent}
.btn-ghost{background:transparent;border:1px solid rgba(0,0,0,0.06);color:var(--ink)}
.hero{padding:48px 0}
.hero-grid{display:grid;grid-template-columns:1fr 360px;gap:28px;align-items:stretch}
.lead{color:var(--muted);margin-top:8px}
.pattern-wrap{position:relative}
.pattern{position:absolute;right:0;top:0;width:100%;height:100%;opacity:0.9}
.hero-card{position:relative;background:var(--card);padding:18px;border-radius:12px;box-shadow:0 8px 30px rgba(13,13,13,0.06);margin-top:40px}
.mood-module{margin-top:20px;background:linear-gradient(180deg,rgba(255,122,77,0.04),transparent);padding:12px;border-radius:10px}
.mood-label{display:block;font-weight:700;margin-bottom:8px}
.mood-options{display:flex;gap:8px;flex-wrap:wrap}
.mood-btn{background:transparent;border:1px solid rgba(29,29,31,0.06);padding:8px 10px;border-radius:8px;cursor:pointer}
.mood-btn.active{background:var(--accent);color:#fff;border-color:var(--accent)}
.mood-result{margin-top:12px;padding:10px;background:rgba(255,255,255,0.5);border-radius:8px}
.method-title{display:block;font-weight:800}
.method-copy{color:var(--muted);margin-top:6px}
.story{padding-top:18px;padding-bottom:18px}
.story-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:18px;margin-top:12px}
.framework{background:rgba(246,241,238,0.6);padding:28px;border-radius:12px;margin-top:18px}
.framework-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin-top:12px}
.offers-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}
.offer{background:var(--card);padding:16px;border-radius:10px;border:1px solid rgba(29,29,31,0.04)}
.pricing{margin-top:18px}
.pricing-toggle{display:flex;align-items:center;gap:12px;margin-bottom:12px}
.toggle{background:transparent;border:1px solid rgba(29,29,31,0.06);padding:8px 12px;border-radius:20px}
.pricing-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}
.plan{background:var(--card);padding:16px;border-radius:12px;border:1px solid rgba(29,29,31,0.04);text-align:center}
.price{font-size:20px;font-weight:800;margin:8px 0}
.price-label{font-size:12px;color:var(--muted);margin-left:6px}
.testimonials{padding-top:18px;padding-bottom:18px}
.testimonials-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:12px}
blockquote{background:#fff;padding:14px;border-radius:10px;border-left:4px solid var(--accent-2)}
cite{display:block;margin-top:8px;color:var(--muted);font-size:13px}
.cta{background:linear-gradient(90deg,rgba(255,122,77,0.08),transparent);padding:28px;border-radius:12px;text-align:center}
.footer-grid{display:flex;justify-content:space-between;gap:12px;align-items:center}
.muted{color:var(--muted)}
@media(max-width:900px){
  .hero-grid{grid-template-columns:1fr}
  .story-grid,.framework-grid,.offers-grid,.pricing-grid,.testimonials-grid{grid-template-columns:1fr}
  .nav{display:none}
  .header-actions{margin-left:0}
}
/* small animated flourish for price changes */
.price-amount{display:inline-block;transition:transform 300ms cubic-bezier(.22,1,.36,1)}
.price-amount.change{transform:translateY(-8px);opacity:0}
"} 
{"path":"assets/js/main.js","content":"(function(){
  // Mood-to-Method modules (two instances)
  function initMoodModule(rootId, copyId, ctaId){
    var root = document.getElementById(rootId);
    if(!root) return;
    var buttons = root.querySelectorAll('.mood-btn');
    var copyEl = document.getElementById(copyId);
    var ctaEl = document.getElementById(ctaId);

    var methods = {
      micro: {
        title: 'Micro-series: focus and repeat',
        text: 'A concentrated 2-week plan with daily prompts and an evening habit to lock progress.',
        cta: 'Try a 2-week micro-series',
        url: '{{PRIMARY_CTA_URL}}'
      },
      rhythm: {
        title: 'Monthly Rhythm: steady practice',
        text: 'Group sessions and short checkpoints that turn one practice into a weekly rhythm.',
        cta: 'Join the Monthly Rhythm',
        url: '{{PRIMARY_CTA_URL}}'
      },
      reset: {
        title: 'Reset Session: quick clarity',
        text: 'A focused 60-minute plan that prioritizes one actionable habit you can start tomorrow.',
        cta: 'Book a Reset Session',
        url: '{{PRIMARY_CTA_URL}}'
      },
      explore: {
        title: 'Short Labs: experiment and learn',
        text: 'Short guided labs to test different approaches before committing to a longer series.',
        cta: 'Explore Short Labs',
        url: '{{PRIMARY_CTA_URL}}'
      }
    };

    buttons.forEach(function(btn){
      btn.addEventListener('click', function(){
        buttons.forEach(function(b){b.classList.remove('active')});
        btn.classList.add('active');
        var key = btn.getAttribute('data-method');
        var entry = methods[key] || methods.micro;
        if(copyEl) copyEl.textContent = entry.title + ' — ' + entry.text;
        if(ctaEl){ ctaEl.textContent = entry.cta; ctaEl.href = entry.url; }
        // Also update top primary CTA to reflect state if present
        var topCta = document.getElementById('primaryCtaTop');
        var bottomCta = document.getElementById('primaryCtaBottom');
        if(topCta) topCta.textContent = entry.cta;
        if(bottomCta) bottomCta.textContent = entry.cta;
      });
    });
  }

  initMoodModule('moodHero','methodCopy','moodCta');
  initMoodModule('moodFramework','methodCopy2','moodCta2');

  // Pricing comparator toggle with animated numbers
  var priceToggle = document.getElementById('priceToggle');
  var pricingGrid = document.getElementById('pricingGrid');
  var monthly = true;

  function animateNumber(el, start, end, duration){
    var startTime = null;
    function step(ts){
      if(!startTime) startTime = ts;
      var progress = Math.min((ts - startTime) / duration, 1);
      var current = Math.round(start + (end - start) * progress);
      el.textContent = '$' + current;
      if(progress < 1){
        requestAnimationFrame(step);
      } else {
        // micro bounce
        el.classList.remove('change');
        void el.offsetWidth;
      }
    }
    requestAnimationFrame(step);
    el.classList.add('change');
  }

  function updatePrices(toMonthly){
    var plans = pricingGrid.querySelectorAll('.plan');
    plans.forEach(function(plan){
      var monthlyVal = parseInt(plan.getAttribute('data-monthly'),10)||0;
      var packageVal = parseInt(plan.getAttribute('data-package'),10)||0;
      var amountEl = plan.querySelector('.price-amount');
      var labelEl = plan.querySelector('.price-label');
      var from = parseInt(amountEl.textContent.replace(/[^0-9]/g,''),10)||0;
      var to = toMonthly ? monthlyVal : packageVal;
      animateNumber(amountEl, from, to, 500);
      labelEl.textContent = toMonthly ? '/month' : '/package';
    });
  }

  if(priceToggle){
    priceToggle.addEventListener('click', function(){
      monthly = !monthly;
      priceToggle.textContent = monthly ? 'Monthly' : 'Package';
      updatePrices(monthly);
    });
  }

  // Setup initial values to reflect data attributes (graceful load)
  document.addEventListener('DOMContentLoaded', function(){
    // Set initial price values from data-monthly
    var plans = document.querySelectorAll('.plan');
    plans.forEach(function(plan){
      var monthlyVal = plan.getAttribute('data-monthly');
      var el = plan.querySelector('.price-amount');
      if(el && monthlyVal) el.textContent = '$' + monthlyVal;
    });
  });
})();"} 
